نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
درآمد فروش این ماه 8% نسبت به ماه قبل افت کرده. دلیلش چیست؟ (مدیر بازرگانی — شرکت مس شهید باهنر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_per_ton",
      "description": "میانگین قیمت فروش هر تن",
      "formula": "درآمد کل / تن فروخته‌شده",
      "unit": "میلیون تومان بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "revenue_per_ton",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "revenue_per_ton": {
    "prev": 221000.0,
    "curr": 213109.31333213797,
    "change_pct": -4
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "prev_month": {
    "revenue_m": 1328,
    "tons": 6009
  },
  "curr_month": {
    "revenue_m": 1222,
    "tons": 5733
  },
  "volume_change_pct": -5
}

نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
گزارش درآمد فروش این ماه را بده: چقدر فروختیم، میانگین قیمت هر تن چقدر بود، و مشتریان اصلی چه سهمی داشتند؟ (مدیر بازرگانی — شرکت سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "customer_portfolio",
      "description": "پرتفوی مشتریان: سهم، ریسک، تاریخچه",
      "dimensions": [
        "customer"
      ],
      "measures": [
        "share_pct",
        "payment_days",
        "volume_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_per_ton",
      "description": "میانگین قیمت فروش هر تن",
      "formula": "درآمد کل / تن فروخته‌شده",
      "unit": "میلیون تومان بر تن",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "customer_concentration",
      "description": "تمرکز فروش (سهم مشتری اول)",
      "formula": "درآمد بزرگ‌ترین مشتری / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "export_share",
      "description": "سهم صادرات از کل فروش",
      "formula": "درآمد صادراتی / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "revenue_per_ton",
      "customer_concentration",
      "export_share"
    ],
    "period": "this_month"
  }
}

TOOL_OBSERVATION:
{
  "revenue_per_ton_m": 0.07,
  "customer_concentration_pct": 30,
  "export_share_pct": 34
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "total_revenue_m": 1417,
  "total_tons": 20523,
  "top_3": [
    {
      "customer": "مشتری_1",
      "share_pct": 16
    },
    {
      "customer": "مشتری_2",
      "share_pct": 20
    },
    {
      "customer": "مشتری_3",
      "share_pct": 16
    }
  ]
}

نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
قرارداد جدید فروش را با قیمت ثابت یا شناور ببندیم؟ مقایسه کن. (مدیر بازرگانی — مجتمع مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "contracts",
      "description": "قراردادهای فروش: قیمت، حجم، شرایط",
      "dimensions": [
        "customer",
        "contract_type"
      ],
      "measures": [
        "volume_tons",
        "price_per_ton",
        "delivery_status"
      ]
    },
    {
      "dataset": "market_prices",
      "description": "قیمت‌های جهانی و داخلی محصولات معدنی",
      "dimensions": [
        "product",
        "benchmark"
      ],
      "measures": [
        "usd_per_ton",
        "toman_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_realization",
      "description": "تحقق قیمت نسبت به مرجع",
      "formula": "قیمت فروش واقعی / قیمت مرجع بازار",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "period": "next_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "fixed_option": {
    "price_per_ton": 186000.0,
    "revenue_m": 2976
  },
  "floating_option": {
    "price_per_ton": 209177,
    "revenue_m": 3347,
    "volatility_pct": 17
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "price_realization"
    ],
    "period": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "realization_trend": [
    0.96,
    1.02,
    0.98
  ]
}

