    "prev": 39,
    "curr": 46
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": "this_month",
      "split": "domestic_export"
    }
  }
}

