گزارش درآمد فروش این ماه را بده: چقدر فروختیم، میانگین قیمت هر تن چقدر بود، و مشتریان اصلی چه سهمی داشتند؟ (مدیر بازرگانی — شرکت سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "customer_portfolio",
      "description": "پرتفوی مشتریان: سهم، ریسک، تاریخچه",
      "dimensions": [
        "customer"
      ],
      "measures": [
        "share_pct",
        "payment_days",
        "volume_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_per_ton",
      "description": "میانگین قیمت فروش هر تن",
      "formula": "درآمد کل / تن فروخته‌شده",
      "unit": "میلیون تومان بر تن",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "customer_concentration",
      "description": "تمرکز فروش (سهم مشتری اول)",
      "formula": "درآمد بزرگ‌ترین مشتری / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "export_share",
      "description": "سهم صادرات از کل فروش",
      "formula": "درآمد صادراتی / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "revenue_per_ton",
      "customer_concentration",
      "export_share"
    ],
    "period": "this_month"
  }
}

TOOL_OBSERVATION:
{
  "revenue_per_ton_m": 0.03,
  "customer_concentration_pct": 33,
  "export_share_pct": 43
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": "this_month"
    }
  }
}

